## test_checkpoint_post.gd  — headless SceneTree test
##
## Run:  godot --headless --path godot --script tests/test_checkpoint_post.gd
## Exit 0 = all PASS, non-zero = failure count.

extends SceneTree

# ─── constants ───────────────────────────────────────────────────────────────

const POST_GLB      := "res://props/checkpoint_post.glb"
const GAME_TSCN     := "res://game.tscn"

# Expected Blender dimensions (Z → Godot Y after Y-up export)
const EXPECT_HEIGHT := 1.80   # Blender Z 0→1.80  = Godot Y extent
const EXPECT_DEPTH  := 0.60   # Blender Y ±0.30   = Godot Z extent
const EXPECT_WIDTH  := 0.78   # Blender X −0.30→0.48 (base + pennant)
const TOL           := 0.01   # 1 cm

# Player capsule height from player.tscn (CapsuleShape3D height = 2.1)
const PLAYER_CAP_H  := 2.10

# Post placed in game.tscn (world space)
const POST_WORLD    := Vector3(-6.5, -3.84189, 3.9334)

# ─── state ───────────────────────────────────────────────────────────────────

var _fails      := 0
var _phys_frame := 0

# ─── entry ───────────────────────────────────────────────────────────────────

func _initialize() -> void:
	_test_prop_scene()

	# Load game scene and wait for physics to settle before the ray test.
	var game := preload(GAME_TSCN).instantiate()
	root.add_child(game)
	physics_frame.connect(_on_physics_frame)


func _on_physics_frame() -> void:
	_phys_frame += 1
	if _phys_frame < 10:
		return
	physics_frame.disconnect(_on_physics_frame)
	_test_game_scene()
	quit(_fails)


# ─── helpers ─────────────────────────────────────────────────────────────────

func _pass(msg: String) -> void:
	print("PASS  ", msg)


func _fail(msg: String) -> void:
	print("FAIL  ", msg)
	_fails += 1


func _check(ok: bool, msg: String) -> void:
	if ok:
		_pass(msg)
	else:
		_fail(msg)


func _approx(a: float, b: float, tol: float) -> bool:
	return abs(a - b) <= tol


# Collect all nodes of a given class recursively.
func _collect(root_node: Node, cls) -> Array:
	var result := []
	for child in root_node.get_children():
		if is_instance_of(child, cls):
			result.append(child)
		result.append_array(_collect(child, cls))
	return result


# Compute merged AABB (world space) of all MeshInstance3D nodes under root_node.
func _merged_aabb(root_node: Node) -> AABB:
	var meshes: Array = _collect(root_node, MeshInstance3D)
	var merged := AABB()
	var first  := true
	for mi: MeshInstance3D in meshes:
		if mi.mesh == null:
			continue
		var local_aabb: AABB = mi.get_aabb()
		# Transform the 8 corners to global space then re-enclose.
		var gt := mi.global_transform
		var corners := [
			gt * local_aabb.position,
			gt * (local_aabb.position + Vector3(local_aabb.size.x, 0.0, 0.0)),
			gt * (local_aabb.position + Vector3(0.0, local_aabb.size.y, 0.0)),
			gt * (local_aabb.position + Vector3(0.0, 0.0, local_aabb.size.z)),
			gt * (local_aabb.position + Vector3(local_aabb.size.x, local_aabb.size.y, 0.0)),
			gt * (local_aabb.position + Vector3(local_aabb.size.x, 0.0, local_aabb.size.z)),
			gt * (local_aabb.position + Vector3(0.0, local_aabb.size.y, local_aabb.size.z)),
			gt * (local_aabb.position + local_aabb.size),
		]
		if first:
			merged = AABB(corners[0], Vector3.ZERO)
			first = false
		for c in corners:
			merged = merged.expand(c)
	return merged


# ─── part 1: prop scene static tests ─────────────────────────────────────────

func _test_prop_scene() -> void:
	print("\n--- Part 1: prop scene static tests ---")

	var ps := preload(POST_GLB)
	var inst := ps.instantiate()
	root.add_child(inst)

	# ── AABB ─────────────────────────────────────────────────────────────────
	var aabb := _merged_aabb(inst)
	print("  merged AABB size: ", aabb.size)

	_check(
		_approx(aabb.size.y, EXPECT_HEIGHT, TOL),
		"visual height (Godot Y) ≈ %.2f m  [got %.4f]" % [EXPECT_HEIGHT, aabb.size.y]
	)
	_check(
		_approx(aabb.size.z, EXPECT_DEPTH, TOL),
		"visual depth  (Godot Z) ≈ %.2f m  [got %.4f]" % [EXPECT_DEPTH, aabb.size.z]
	)
	_check(
		_approx(aabb.size.x, EXPECT_WIDTH, TOL),
		"visual width  (Godot X) ≈ %.2f m  [got %.4f]" % [EXPECT_WIDTH, aabb.size.x]
	)

	# ── unit scale on every MeshInstance3D ───────────────────────────────────
	var meshes: Array = _collect(inst, MeshInstance3D)
	var all_unit_scale := true
	for mi: MeshInstance3D in meshes:
		if not _approx(mi.scale.x, 1.0, 0.001) or \
		   not _approx(mi.scale.y, 1.0, 0.001) or \
		   not _approx(mi.scale.z, 1.0, 0.001):
			all_unit_scale = false
			print("  non-unit scale on: ", mi.name, " scale=", mi.scale)
	_check(all_unit_scale, "all MeshInstance3D have unit scale")

	# ── materials: only PostMetal and FlagCloth ───────────────────────────────
	var mat_names := {}
	for mi: MeshInstance3D in meshes:
		for i in range(mi.get_surface_override_material_count()):
			var mat := mi.mesh.surface_get_material(i)
			if mat:
				mat_names[mat.resource_name] = true
	print("  material names found: ", mat_names.keys())
	var only_expected := true
	for name in mat_names.keys():
		if name != "PostMetal" and name != "FlagCloth":
			only_expected = false
	var has_metal := mat_names.has("PostMetal")
	var has_cloth := mat_names.has("FlagCloth")
	_check(has_metal,     "PostMetal material present")
	_check(has_cloth,     "FlagCloth material present")
	_check(only_expected, "no unexpected materials  [found %s]" % str(mat_names.keys()))

	# ── StaticBody3D with ConvexPolygonShape3D ────────────────────────────────
	var bodies: Array = _collect(inst, StaticBody3D)
	_check(bodies.size() >= 1, "at least one StaticBody3D present  [found %d]" % bodies.size())

	var found_convex := false
	var convex_pts   := PackedVector3Array()
	for body: StaticBody3D in bodies:
		for col_child in body.get_children():
			if col_child is CollisionShape3D:
				var shape := (col_child as CollisionShape3D).shape
				if shape is ConvexPolygonShape3D:
					found_convex = true
					convex_pts   = (shape as ConvexPolygonShape3D).points
					break
		if found_convex:
			break

	_check(found_convex, "StaticBody3D has a ConvexPolygonShape3D")

	if found_convex and convex_pts.size() > 0:
		# Collision bounds in LOCAL space of the imported root (origin = base underside)
		var cx_min := INF; var cx_max := -INF
		var cy_min := INF; var cy_max := -INF
		var cz_min := INF; var cz_max := -INF
		for pt in convex_pts:
			# convex hull points are in the StaticBody3D's local frame; because
			# all transforms were applied in Blender, the StaticBody3D is at
			# origin so local == scene-root local.
			cx_min = min(cx_min, pt.x); cx_max = max(cx_max, pt.x)
			cy_min = min(cy_min, pt.y); cy_max = max(cy_max, pt.y)
			cz_min = min(cz_min, pt.z); cz_max = max(cz_max, pt.z)
		print("  convex hull bounds  X[%.3f,%.3f] Y[%.3f,%.3f] Z[%.3f,%.3f]"
			  % [cx_min, cx_max, cy_min, cy_max, cz_min, cz_max])

		# Covers base bottom (Y ≈ 0) and pole top (Y ≈ 1.8)
		_check(cy_min <= 0.01,          "collision covers base floor (Y_min ≈ 0)")
		_check(cy_max >= EXPECT_HEIGHT - 0.05,  "collision covers pole top  (Y_max ≈ 1.8)")
		# X bound ≤ 0.35 — covers base (±0.30) but not pennant tip (X=0.48)
		_check(cx_max <= 0.35,          "collision X_max ≤ 0.35 (base, not pennant) [got %.3f]" % cx_max)

	# ── prop shorter than player capsule ─────────────────────────────────────
	_check(
		EXPECT_HEIGHT < PLAYER_CAP_H,
		"prop height %.2f < player capsule %.2f" % [EXPECT_HEIGHT, PLAYER_CAP_H]
	)

	inst.queue_free()
	print()


# ─── part 2: game.tscn physics + ray test ────────────────────────────────────

func _test_game_scene() -> void:
	print("--- Part 2: game.tscn physics + ray test ---")

	var space_state := root.get_world_3d().direct_space_state
	if space_state == null:
		_fail("could not get physics space state")
		return

	# Cast downward from 2 m above the post, to 2 m below its base.
	var from := POST_WORLD + Vector3(0.0, 2.0, 0.0)
	var to   := POST_WORLD + Vector3(0.0, -2.0, 0.0)
	var qry  := PhysicsRayQueryParameters3D.create(from, to)
	var hit  := space_state.intersect_ray(qry)

	print("  ray from=%s  to=%s" % [from, to])

	_check(not hit.is_empty(), "downward ray hits something (post/floor is solid)")

	if not hit.is_empty():
		var hit_y: float = hit.position.y
		print("  ray hit at y=%.4f  (post base y=%.4f, top y≈%.4f)"
			  % [hit_y, POST_WORLD.y, POST_WORLD.y + EXPECT_HEIGHT])

		# Ray should strike the top of the collision box, not the floor below.
		_check(
			hit_y > POST_WORLD.y + 0.1,
			"ray hits above floor level (post collision is standing on floor)  [hit_y=%.4f]" % hit_y
		)

	print()
	print("Failures: %d" % _fails)

extends SceneTree
func _initialize() -> void:
	var ps := preload("res://props/checkpoint_post.glb")
	var inst := ps.instantiate()
	root.add_child(inst)
	await process_frame
	_print_tree(inst, "")
	quit(0)

func _print_tree(n: Node, indent: String) -> void:
	var extra := ""
	if n is CollisionShape3D:
		var cs := n as CollisionShape3D
		if cs.shape:
			extra = " shape=" + cs.shape.get_class()
	print(indent + n.get_class() + " [" + n.name + "]" + extra)
	for c in n.get_children():
		_print_tree(c, indent + "  ")

