# ─── part 2: game.tscn physics + ray test ────────────────────────────────────

func _test_game_scene() -> void:
	print("--- Part 2: game.tscn physics + ray test ---")

	var space_state := root.get_world_3d().direct_space_state
	if space_state == null:
		_fail("could not get physics space state")
		return

	# Ray from 2 m above the post's top, to 2 m below its base.
	var from := POST_WORLD + Vector3(0.0,  2.0 + EXPECT_HEIGHT, 0.0)
	var to   := POST_WORLD + Vector3(0.0, -2.0,                  0.0)
	var qry  := PhysicsRayQueryParameters3D.create(from, to)
	var hit  := space_state.intersect_ray(qry)

	print("  ray from=%s  to=%s" % [str(from), str(to)])

	_check(not hit.is_empty(), "downward ray hits something (post or floor is solid)")

	if not hit.is_empty():
		var hit_y: float = hit.position.y
		var post_top_y := POST_WORLD.y + EXPECT_HEIGHT
		print("  ray hit at y=%.4f  (post base y=%.4f, post top y≈%.4f)"
			  % [hit_y, POST_WORLD.y, post_top_y])

		# Hit should be at the top of the collision box, not just the floor.
		_check(
			hit_y > POST_WORLD.y + 0.2,
			"ray hits above base level — post collision is solid above floor  [hit_y=%.4f > %.4f]"
			% [hit_y, POST_WORLD.y + 0.2]
		)

	print()
	print("Failures: %d" % _fails)
